#include "drone_config.h"
#include "nvs.h"
#include "freertos/FreeRTOS.h"
#include <string.h>
#define CFG_VERSION 1u
typedef struct { uint32_t version; whoopy_pid_cfg_t roll,pitch,yaw; float max_angle_deg,max_rate_dps,max_motor_output,complementary_alpha; uint16_t failsafe_ms; uint8_t acro; } legacy_config_t;
static portMUX_TYPE config_mux=portMUX_INITIALIZER_UNLOCKED;
void config_snapshot(const drone_config_t*source,drone_config_t*destination){if(!source||!destination)return;portENTER_CRITICAL(&config_mux);memcpy(destination,source,sizeof(*destination));portEXIT_CRITICAL(&config_mux);}
void config_replace(drone_config_t*destination,const drone_config_t*source){if(!source||!destination)return;portENTER_CRITICAL(&config_mux);memcpy(destination,source,sizeof(*destination));portEXIT_CRITICAL(&config_mux);}
void config_defaults(drone_config_t*c){*c=(drone_config_t){.version=CFG_VERSION,.roll={.kp=.012f,.ki=.003f,.kd=.0002f,.limit=.25f,.integral_limit=10},.pitch={.kp=.012f,.ki=.003f,.kd=.0002f,.limit=.25f,.integral_limit=10},.yaw={.kp=.008f,.ki=.002f,.kd=0,.limit=.18f,.integral_limit=10},.max_angle_deg=20,.max_rate_dps=180,.max_motor_output=.75f,.complementary_alpha=.98f,.failsafe_ms=250,.acro=0,.motor_map={0,1,2,3}};}
bool config_valid(const drone_config_t*c){if(!c||c->version!=CFG_VERSION||!whoopy_config_valid(&c->roll,c->max_angle_deg,c->max_rate_dps,c->failsafe_ms)||!whoopy_config_valid(&c->pitch,c->max_angle_deg,c->max_rate_dps,c->failsafe_ms)||!whoopy_config_valid(&c->yaw,c->max_angle_deg,c->max_rate_dps,c->failsafe_ms)||c->max_motor_output<.1f||c->max_motor_output>1.0f||c->complementary_alpha<.90f||c->complementary_alpha>.999f||c->acro>1)return false;uint8_t seen=0;for(int i=0;i<4;i++){if(c->motor_map[i]>3||(seen&(1u<<c->motor_map[i])))return false;seen|=(uint8_t)(1u<<c->motor_map[i]);}return true;}
esp_err_t config_load(drone_config_t*c){config_defaults(c);nvs_handle_t h;esp_err_t e=nvs_open("whoopy",NVS_READONLY,&h);if(e!=ESP_OK)return e;size_t n=0;e=nvs_get_blob(h,"cfg",NULL,&n);if(e==ESP_OK&&n==sizeof(*c))e=nvs_get_blob(h,"cfg",c,&n);else if(e==ESP_OK&&n==sizeof(legacy_config_t)){legacy_config_t old;e=nvs_get_blob(h,"cfg",&old,&n);if(e==ESP_OK){c->version=old.version;c->roll=old.roll;c->pitch=old.pitch;c->yaw=old.yaw;c->max_angle_deg=old.max_angle_deg;c->max_rate_dps=old.max_rate_dps;c->max_motor_output=old.max_motor_output;c->complementary_alpha=old.complementary_alpha;c->failsafe_ms=old.failsafe_ms;c->acro=old.acro;}}else if(e==ESP_OK)e=ESP_ERR_INVALID_SIZE;nvs_close(h);if(e!=ESP_OK||!config_valid(c)){config_defaults(c);return ESP_ERR_INVALID_STATE;}return ESP_OK;}
esp_err_t config_save(const drone_config_t*c){if(!config_valid(c))return ESP_ERR_INVALID_ARG;nvs_handle_t h;esp_err_t e=nvs_open("whoopy",NVS_READWRITE,&h);if(e!=ESP_OK)return e;e=nvs_set_blob(h,"cfg",c,sizeof(*c));if(e==ESP_OK)e=nvs_commit(h);nvs_close(h);return e;}
